CREATE OR REPLACE FUNCTION public.guard_ip_access_policy()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM id FROM "Company" WHERE id=NEW."tenantId" FOR UPDATE;
  IF TG_OP='INSERT' AND NEW.version<>1 THEN RAISE EXCEPTION 'IP policy initial version' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND (NEW."tenantId"<>OLD."tenantId" OR NEW.version<>OLD.version+1) THEN
    RAISE EXCEPTION 'IP policy version or scope' USING ERRCODE='23514';
  END IF;
  IF NEW.enabled AND NOT EXISTS(SELECT 1 FROM "IpRule" WHERE "tenantId"=NEW."tenantId" AND enabled) THEN
    RAISE EXCEPTION 'Enabled IP restriction needs an enabled rule' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_ip_rule()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE company_id TEXT; remaining INTEGER;
BEGIN
  company_id := CASE WHEN TG_OP='DELETE' THEN OLD."tenantId" ELSE NEW."tenantId" END;
  PERFORM id FROM "Company" WHERE id=company_id FOR UPDATE;
  IF TG_OP='INSERT' THEN
    IF NEW.version<>1 THEN RAISE EXCEPTION 'IP rule initial version' USING ERRCODE='23514'; END IF;
  ELSIF TG_OP='UPDATE' THEN
    IF NEW.id<>OLD.id OR NEW."tenantId"<>OLD."tenantId" OR NEW.version<>OLD.version+1 THEN
      RAISE EXCEPTION 'IP rule version or scope' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_OP<>'INSERT' AND EXISTS(SELECT 1 FROM "IpAccessPolicy" WHERE "tenantId"=company_id AND enabled) THEN
    SELECT count(*) INTO remaining FROM "IpRule" WHERE "tenantId"=company_id AND enabled AND id<>OLD.id;
    IF remaining=0 AND (TG_OP='DELETE' OR NOT NEW.enabled) THEN
      RAISE EXCEPTION 'Enabled IP restriction needs an enabled rule' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_mfa_exception()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM id FROM "Company" WHERE id=NEW."tenantId" FOR UPDATE;
  IF TG_OP='INSERT' AND NEW.version<>1 THEN RAISE EXCEPTION 'MFA exception initial version' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW."tenantId"<>OLD."tenantId" OR NEW."memberId"<>OLD."memberId" OR NEW."createdById"<>OLD."createdById" OR NEW."createdAt"<>OLD."createdAt" OR NEW.version<>OLD.version+1) THEN
    RAISE EXCEPTION 'MFA exception scope or version' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.invalidate_export_access()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE row_data jsonb; actor_id text; tenant_id text; service_id text;
BEGIN
  IF TG_OP='INSERT' THEN row_data:=to_jsonb(NEW); ELSE row_data:=to_jsonb(OLD); END IF;
  tenant_id:=row_data->>'tenantId';
  IF TG_TABLE_NAME='User' THEN actor_id:=row_data->>'id';
  ELSIF TG_TABLE_NAME='Company' THEN tenant_id:=row_data->>'id';
  ELSIF TG_TABLE_NAME='Service' THEN service_id:=row_data->>'id';
  ELSIF TG_TABLE_NAME='Membership' THEN actor_id:=row_data->>'userId';
  ELSIF TG_TABLE_NAME='ExpertAssignment' THEN actor_id:=row_data->>'expertUserId';
  ELSIF TG_TABLE_NAME='ServiceGrant' THEN
    SELECT "userId" INTO actor_id FROM "Membership" WHERE id=row_data->>'memberId' AND "tenantId"=tenant_id;
    service_id:=row_data->>'serviceId';
  ELSIF TG_TABLE_NAME='ExpertAssignmentService' THEN
    SELECT "expertUserId" INTO actor_id FROM "ExpertAssignment" WHERE id=row_data->>'assignmentId' AND "tenantId"=tenant_id;
    service_id:=row_data->>'serviceId';
  END IF;
  PERFORM erase_export_jobs(ARRAY(SELECT id FROM "ExportJob" WHERE (tenant_id IS NULL OR "tenantId"=tenant_id) AND (actor_id IS NULL OR "requesterId"=actor_id) AND (service_id IS NULL OR "serviceId"=service_id)),'ACCESS_CHANGED');
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$
